return items.map(item => {
  // 1) Metadaten pro Item holen (nach Restore)
  const groupName = item.json.currentGroupName || 'Unbekannte Gruppe';
  const mainTheme = item.json.mainTheme || 'Vorbereitungsmaterial';

  // ROBUSTE Extraktion für ALLE wichtigen Felder
  const getValue = (val) => {
    if (val === null || val === undefined) return null;
    if (Array.isArray(val)) return val[0] || null;
    return val;
  };

  const sermon_id = getValue(item.json.sermon_id);
  const user_id   = getValue(item.json.user_id);
  const title     = getValue(item.json.title);
  const original_file_name = getValue(item.json.original_file_name);

  // 2) Footer
  const footerRecipient = item.json.sendToEmail || groupName || 'den Empfänger';

  // 3) Sicheren Dateinamen bauen (aus groupName + mainTheme)
  const rawBase = `${groupName}_${mainTheme}`;
  const safeBase = rawBase
    .toString()
    .replace(/[^a-zA-Z0-9äöüÄÖÜß]/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_+|_+$/g, '');
  const fileName = `${safeBase}.doc`;

  // 4) HTML-Content
  let rawContent = item.json.output ||
                   item.json.text ||
                   item.json.formatted_content ||
                   item.json.content ||
                   'Kein Inhalt generiert.';

  const cleanContent = (text) => {
    if (!text) return '';
    let cleaned = text.toString()
      .replace(/<!DOCTYPE[^>]*>/gi, '')
      .replace(/<html[^>]*>/gi, '')
      .replace(/<\/html>/gi, '')
      .replace(/<head[^>]*>[\s\S]*?<\/head>/gi, '')
      .replace(/<body[^>]*>/gi, '')
      .replace(/<\/body>/gi, '')
      .replace(/<meta[^>]*>/gi, '')
      .replace(/<title[^>]*>[\s\S]*?<\/title>/gi, '')
      .trim();
    return cleaned || '<p>Kein Inhalt generiert.</p>';
  };

  const finalBodyContent = cleanContent(rawContent);

  // 5) HTML-Template
  const htmlContent = `
<!DOCTYPE html>
<html lang="de">
<head>
  <meta charset="UTF-8" />
  <meta http-equiv="Content-Type" content="text/html; charset=utf-8" />
  <title>KirchenKI ${groupName}</title>
  <style>
    :root {
      --primary: #6b806c;
      --primary-soft: rgba(107, 128, 108, 0.12);
      --accent: #6b806c;
      --text-main: #111827;
      --text-soft: #4b5563;
      --bg: #ffffff;
      --card: #f3f4f6;
      --border: #e5e7eb;
    }
    * { box-sizing: border-box; }
    body {
      font-family: Inter, "Helvetica Neue", Helvetica, Arial, sans-serif;
      line-height: 1.7;
      color: var(--text-main);
      background: var(--bg);
      padding: 40px;
      margin: 0;
    }
    .header {
      border-bottom: 1px solid var(--border);
      margin-bottom: 30px;
      padding-bottom: 20px;
    }
    .tag {
      display: inline-block;
      background: var(--primary-soft);
      color: var(--accent);
      padding: 4px 10px;
      border-radius: 999px;
      font-size: 12px;
      margin-bottom: 10px;
      font-weight: 600;
    }
    h1 { margin: 0; font-size: 28px; color: var(--primary); }
    .subtitle { color: var(--text-soft); font-size: 14px; margin-top: 8px; }
    .content { font-size: 15px; color: var(--text-soft); }
    hr { border: none; border-top: 1px solid var(--border); margin: 30px 0; }
    small { color: #999999; }
  </style>
</head>
<body>
  <div class="header">
    <div class="tag">${groupName}</div>
    <h1>${groupName}</h1>
    <div class="subtitle">KirchenKI Studienmaterial – ${mainTheme}</div>
  </div>
  <div class="content">
    ${finalBodyContent}
  </div>
  <br /><br />
  <hr />
  <small>Erstellt für ${footerRecipient} – Generiert mit KirchenKI</small>
</body>
</html>
`.trim();


  // E-Mail direkt aus den Original-Webhook-Daten pro Gruppe nachschlagen
  // 6) E-Mail-Daten: Per-Gruppe aus Webhook nachschlagen
  const webhookBody = $('Webhook from kirchenki.com').first().json.body || {};
  let groupEmailsMap = {};
  try { groupEmailsMap = JSON.parse(webhookBody.groupEmails || '{}'); } catch(e) {}
  const trimmedGroup = groupName.trim();
  const matchingKey = Object.keys(groupEmailsMap).find(
    key => key.trim().toLowerCase() === trimmedGroup.toLowerCase()
  );
  const groupEmailList = matchingKey ? groupEmailsMap[matchingKey] : [];
  const sendToEmail = groupEmailList[0] || webhookBody.email || 'admin@kirchenki.com';
  const subjectPrefix = `Material für ${groupName}`;

  // 7) Ergebnis zurückgeben
  return {
    json: {
      htmlContent: htmlContent,
      fileName: fileName,
      currentGroupName: groupName,
      mainTheme: mainTheme,
      sendToEmail: sendToEmail,
      subjectPrefix: subjectPrefix,
      sermon_id: $("Restore Metadata").first().json.sermon_id,
      user_id: $("Restore Metadata").first().json.user_id,
      title: $("Restore Metadata").first().json.title,
      original_file_name: $("Restore Metadata").first().json.original_file_name
    }
  };
});

const binaryKeys = Object.keys($input.first().binary || {});
if (binaryKeys.length > 0) {
  const sourceKey = binaryKeys[0];
  $input.first().binary.file = $input.first().binary[sourceKey];
  if (sourceKey !== 'file') {
    delete $input.first().binary[sourceKey];
  }
}
return $input.all();

// Parse the webhook body data
const body = $input.first().json.body;

// Parse groups string to array
let kleingruppen = [];
if (body.groups) {
  try {
    kleingruppen = JSON.parse(body.groups);
  } catch (e) {
    kleingruppen = body.groups.split(',').map(g => g.trim()).filter(g => g);
  }
}

// Parse groupEmails string to object
let groupEmails = {};
if (body.groupEmails) {
  try {
    groupEmails = JSON.parse(body.groupEmails);
  } catch (e) {
    groupEmails = {};
  }
}

// Parse recipientEmails string to array
let recipientEmails = [];
if (body.recipientEmails) {
  try {
    recipientEmails = JSON.parse(body.recipientEmails);
  } catch (e) {
    if (typeof body.recipientEmails === 'string') {
      recipientEmails = body.recipientEmails
        .split(',')
        .map(e => e.trim())
        .filter(e => e);
    } else {
      recipientEmails = [];
    }
  }
}

// Neue Felder von der Edge Function
const sermon_id = body.sermon_id || null;
const user_id = body.user_id || null;
const title = body.title || null;
const original_file_name = body.original_file_name || null;

// Convert nurTranskript string to boolean
let nurTranskript = false;
if (body.nurTranskript) {
  nurTranskript = body.nurTranskript === 'true' || body.nurTranskript === '1' || body.nurTranskript === true;
}

// Get email from body
const email = body.email || '';

// Preserve all original data and add parsed fields
const output = {
  ...($input.first().json),
  kleingruppen: kleingruppen,
  groupEmails: groupEmails,
  recipientEmails: recipientEmails,
  nurTranskript: nurTranskript,
  email: email,

  // Neue Felder für Supabase-Verknüpfung
  sermon_id: sermon_id,
  user_id: user_id,
  title: title,
  original_file_name: original_file_name
};

// Preserve binary data if present
const binary = $input.first().binary || {};

return [{ json: output, binary: binary }];

// Sichere Metadaten in "meta"-Objekt
const item = items[0];

item.json.meta = {
    groups: item.json.kleingruppen || [],
    groupEmails: item.json.groupEmails || {},
    recipientEmails: item.json.recipientEmails || [],
    email: item.json.email || '',
    nurTranskript: item.json.nurTranskript || false
};

return items;

return items.map(item => {
    const saveData = $('save data').first().json || {};
    const webhookBody = $('Webhook from kirchenki.com').first().json.body || {};

    // groupEmails Mapping parsen
    let groupEmailsMap = {};
    try { groupEmailsMap = JSON.parse(webhookBody.groupEmails || '{}'); } catch(e) {}

    // Pro Datenelement die richtige E-Mail setzen
    if (item.json.data && Array.isArray(item.json.data)) {
        item.json.data = item.json.data.map(d => {
            const gName = (d.currentGroupName || '').trim();
            const matchKey = Object.keys(groupEmailsMap).find(
                k => k.trim().toLowerCase() === gName.toLowerCase()
            );
            d.sendToEmail = matchKey
                ? (groupEmailsMap[matchKey][0] || webhookBody.email || 'admin@kirchenki.com')
                : (webhookBody.email || 'admin@kirchenki.com');
            return d;
        });
    }

    // Supabase-Felder
    item.json.sermon_id = saveData._saved_sermon_id || null;
    item.json.user_id   = saveData._saved_user_id   || null;
    item.json.title     = saveData._saved_title || webhookBody.title || null;
    item.json.original_file_name = webhookBody.original_file_name ||
                                   saveData._saved_original_file_name || null;
    item.json.mainTheme = saveData._saved_mainTheme ||
                          $('Summarize and Format Sermon').first().json.output?.mainTheme ||
                          'Ihre Predigt';

    return item;
});

const baseData = items[0].json;

// Webhook-Daten holen
const webhookData = $('Webhook from kirchenki.com').first().json.body;

let groupsArray = [];
if (webhookData.groups) {
    try {
        groupsArray = JSON.parse(webhookData.groups);
    } catch (e) {
        groupsArray = webhookData.groups.split(',').map(g => g.trim()).filter(g => g);
    }
}

let groupEmailsObj = {};
if (webhookData.groupEmails) {
    try {
        groupEmailsObj = JSON.parse(webhookData.groupEmails);
    } catch (e) {
        groupEmailsObj = {};
    }
}

const fallbackEmail = (webhookData.email || '').trim();

const newItems = [];

// Pro Gruppe iterieren
for (const groupName of groupsArray) {
    // E-Mail-Liste für diese Gruppe holen (Array)
    let emailArray = [];
    let groupKey = groupName;

    if (groupEmailsObj[groupKey]) {
        emailArray = groupEmailsObj[groupKey];
    } else {
        // Case-insensitive Match versuchen
        const matchingKey = Object.keys(groupEmailsObj).find(
            key => key.toLowerCase().trim() === groupName.toLowerCase().trim()
        );
        if (matchingKey) {
            emailArray = groupEmailsObj[matchingKey];
        }
    }

    // Sicherstellen, dass es ein Array mit validen E-Mails ist
    emailArray = emailArray
        ? emailArray.map(e => e.trim()).filter(e => e && e.includes('@'))
        : [];

    // Wenn keine spezifischen E-Mails → Fallback nutzen
    if (emailArray.length === 0 && fallbackEmail) {
        emailArray = [fallbackEmail];
    }

    // Pro E-Mail-Adresse ein separates Item erzeugen
    for (const singleEmail of emailArray) {
        newItems.push({
            json: {
                ...baseData,
                currentGroupName: groupName,
                sendToEmail: singleEmail   // Nur eine Adresse pro Item
            }
        });
    }
}

// Fallback, falls gar keine Gruppen/E-Mails
if (newItems.length === 0 && fallbackEmail) {
    newItems.push({
        json: {
            ...baseData,
            currentGroupName: 'Unbekannte Gruppe',
            sendToEmail: fallbackEmail
        }
    });
}

return newItems;

return items.map(item => {
    let groupName = (item.json.currentGroupName || "").toString().trim();

    // Optional: Kleinere Normalisierung für Sicherheit (z. B. "Jungschar / Royal Ranger" bleibt gleich)
    // Aber trim entfernt Leerzeichen – das ist der Hauptfix

    item.json.currentGroupNameNormalized = groupName;

    return item;
});

const webhookBody = $('Webhook from kirchenki.com').first().json.body || {};
let groupEmailsMap = {};
try { groupEmailsMap = JSON.parse(webhookBody.groupEmails || '{}'); } catch(e) {}

const codeItems = $('Code in JavaScript').all();

return items.map((item, index) => {
    const groupName = (codeItems[index]?.json?.currentGroupName || '').trim();

    const matchKey = Object.keys(groupEmailsMap).find(
        k => k.trim().toLowerCase() === groupName.toLowerCase()
    );

    item.json.sendToEmail = matchKey 
        ? (groupEmailsMap[matchKey][0] || webhookBody.email || 'admin@kirchenki.com')
        : (webhookBody.email || 'admin@kirchenki.com');
    item.json.currentGroupName = groupName;

    return item;
});

const item = $input.first();
const binary = item.binary?.file;

if (!binary) return [{ json: { text: '', ...item.json } }];

// DOCX ist eine ZIP-Datei mit XML-Inhalt
const buffer = Buffer.from(binary.data, 'base64');
const str = buffer.toString('latin1');

// Extrahiert <w:t> Text-Elemente aus dem Word-XML
const matches = str.match(/<w:t[\s>][^<]*<\/w:t>/g) || [];
const text = matches
  .map(m => m.replace(/<[^>]+>/g, '').trim())
  .filter(t => t.length > 0)
  .join(' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{ json: { text: text || 'Kein Text extrahiert', ...item.json } }];
